3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireUser } from "./auth";
6	import { requireArea } from "./rbac";
7	import { GAME_FAMILIES, type GameFamily } from "./games";
8	
9	/**
10	 * Update Announcements — service-specific release notes pushed to customers.
11	 *
12	 * Admin creates a DRAFT, then explicitly publishes it (the approval gate).
13	 * Customers see a popup on first login after publish and a persistent
14	 * "What's New" feed. `serviceTypes` scopes visibility: a user only sees
15	 * announcements for services they actually have; empty = everyone.
16	 *
17	 * Admin actions are area-gated ("platform"). Customer actions self-auth via
18	 * `requireUser()` and only ever touch that user's own rows.
19	 */
20	
21	/** Widened from the original 4 to match the concept's filter row and every
22	 *  real product area — DOMAINS/BILLING/PLATFORM were previously unrepresentable
23	 *  (an admin authoring a domains or platform-wide update had nowhere to put it
24	 *  but the general "empty = everyone" bucket). */
25	const SERVICE_TYPES = ["GAME", "VPS", "HOSTING", "DOMAINS", "MAIL", "BILLING", "PLATFORM"] as const;
26	export type ServiceType = (typeof SERVICE_TYPES)[number];
27	
28	/** What kind of change an update is — author-set, drives the What's New
29	 *  page's icon/tone/filter. Never inferred from the title. */
30	const KINDS = ["FEATURE", "IMPROVEMENT", "BUGFIX"] as const;
31	export type AnnouncementKind = (typeof KINDS)[number];
32	
33	// ---------- Admin ----------
34	
35	export async function listAnnouncements() {
36	  await requireArea("platform");
37	  return db.updateAnnouncement.findMany({
38	    orderBy: { createdAt: "desc" },
39	    take: 200,
40	    include: { _count: { select: { seenBy: true } } },
41	  });
42	}
