44	export async function createAnnouncement(input: {
45	  title: string;
46	  body: string;
47	  kind?: string;
48	  serviceTypes: string[];
49	  gameFamilies?: string[];
50	  screenshotUrl?: string | null;
51	}): Promise<{ error?: string; ok?: boolean }> {
52	  await requireArea("platform");
53	  const title = String(input.title ?? "").trim();
54	  if (!title) return { error: "Enter a title." };
55	  const body = String(input.body ?? "").trim();
56	  if (!body) return { error: "Enter a body." };
57	
58	  const kind = (KINDS as readonly string[]).includes(input.kind ?? "") ? (input.kind as AnnouncementKind) : "FEATURE";
59	
60	  // Validate service types — only allow known values.
61	  const serviceTypes = (input.serviceTypes ?? []).filter((t) =>
62	    (SERVICE_TYPES as readonly string[]).includes(t),
63	  );
64	
65	  // Game families only make sense when the update is GAME-scoped. Validate
66	  // against the real game family list so a typo can never silently no-op.
67	  const gameFamilies = serviceTypes.includes("GAME")
68	    ? (input.gameFamilies ?? []).filter((g) => (GAME_FAMILIES as readonly string[]).includes(g))
69	    : [];
70	
71	  // Screenshot must be a relative path, not an external URL.
72	  let screenshotUrl: string | null = null;
73	  if (input.screenshotUrl) {
74	    const u = input.screenshotUrl.trim();
75	    if (u && !u.startsWith("/")) return { error: "Screenshot must be a relative path (e.g. /uploads/announcements/img.png)." };
76	    screenshotUrl = u || null;
77	  }
78	
79	  await db.updateAnnouncement.create({
80	    data: {
81	      title: title.slice(0, 200),
82	      body: body.slice(0, 10_000),
83	      kind,
84	      serviceTypes,
85	      gameFamilies,
86	      screenshotUrl,
87	      status: "DRAFT",
88	    },
89	  });
90	  revalidatePath("/admin/announcements");
91	  return { ok: true };
92	}
