187	export type WhatsNewEntry = {
188	  id: string;
189	  title: string;
190	  body: string;
191	  kind: AnnouncementKind;
192	  serviceTypes: string[];
193	  gameFamilies: string[];
194	  screenshotUrl: string | null;
195	  publishedAt: string; // ISO string for serialization
196	  seen: boolean;
197	};
198	
199	/**
200	 * All PUBLISHED announcements, optionally filtered by service type, ordered
201	 * by publishedAt desc, with a `seen` boolean flag for the current user.
202	 */
203	export async function getWhatsNew(
204	  serviceFilter?: string,
205	): Promise<WhatsNewEntry[]> {
206	  const user = await requireUser();
207	
208	  const where: Record<string, unknown> = { status: "PUBLISHED" };
209	  if (serviceFilter && (SERVICE_TYPES as readonly string[]).includes(serviceFilter)) {
210	    where.serviceTypes = { has: serviceFilter };
211	  }
212	
213	  const announcements = await db.updateAnnouncement.findMany({
214	    where,
215	    orderBy: { publishedAt: "desc" },
216	    include: {
217	      seenBy: {
218	        where: { userId: user.id },
219	        take: 1,
220	      },
221	    },
222	  });
223	
224	  return announcements.map((a) => ({
225	    id: a.id,
226	    title: a.title,
227	    body: a.body,
228	    kind: ((KINDS as readonly string[]).includes(a.kind) ? a.kind : "FEATURE") as AnnouncementKind,
229	    serviceTypes: a.serviceTypes,
230	    gameFamilies: a.gameFamilies,
231	    screenshotUrl: a.screenshotUrl,
232	    publishedAt: (a.publishedAt ?? a.createdAt).toISOString(),
233	    seen: a.seenBy.length > 0,
234	  }));
235	}
236	
237	/**
238	 * Real counts behind the What's New page's stats card — every number here is
239	 * a straight aggregate over PUBLISHED rows, never estimated. "Major releases"
240	 * and "Fixes & improvements" are just `kind` grouped two ways, not a second
241	 * concept: a FEATURE is the "major" half, IMPROVEMENT + BUGFIX are the other.
242	 */
243	export async function getWhatsNewStats(): Promise<{
244	  total: number; newThisMonth: number; majorReleases: number; fixesAndImprovements: number;
245	}> {
246	  const monthStart = new Date();
247	  monthStart.setDate(1);
248	  monthStart.setHours(0, 0, 0, 0);
249	  const base = { status: "PUBLISHED" } as const;
250	  const [total, newThisMonth, majorReleases, fixesAndImprovements] = await Promise.all([
251	    db.updateAnnouncement.count({ where: base }),
252	    db.updateAnnouncement.count({ where: { ...base, publishedAt: { gte: monthStart } } }),
253	    db.updateAnnouncement.count({ where: { ...base, kind: "FEATURE" } }),
254	    db.updateAnnouncement.count({ where: { ...base, kind: { in: ["IMPROVEMENT", "BUGFIX"] } } }),
255	  ]);
256	  return { total, newThisMonth, majorReleases, fixesAndImprovements };
257	}
