"use client";

import { useEffect, useState, useTransition, useCallback } from "react";
import { createPortal } from "react-dom";
import {
  getUnseenAnnouncements,
  markAnnouncementSeen,
} from "@/lib/actions-announcements";
import { renderMarkdown } from "@/lib/blog";
import { GameCoverTile } from "@/components/customer/GameCoverTile";
import { GAME_DISPLAY, type GameFamily } from "@/lib/games";

type Announcement = {
  id: string;
  title: string;
  body: string;
  screenshotUrl: string | null;
  serviceTypes: string[];
  gameFamilies: string[];
  publishedAt: Date | null;
};

/**
 * Shows unseen update announcements as a modal popup, one at a time.
 * Mounted inside the dashboard layout so it only fires for authenticated users.
 * Uses createPortal to escape any transformed ancestors (same fix as
 * HeardAboutUsPrompt.tsx).
 */
export function AnnouncementPopup() {
  const [queue, setQueue] = useState<Announcement[]>([]);
  const [loaded, setLoaded] = useState(false);
  const [, startTransition] = useTransition();

  useEffect(() => {
    let cancelled = false;
    getUnseenAnnouncements()
      .then((items) => {
        if (!cancelled) {
          setQueue(items);
          setLoaded(true);
        }
      })
      .catch(() => {
        // Soft-fail: never block the portal over a failed announcement fetch.
        if (!cancelled) setLoaded(true);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  const dismiss = useCallback(() => {
    const current = queue[0];
    if (!current) return;
    // Remove from queue optimistically.
    setQueue((prev) => prev.slice(1));
    // Persist the seen record in the background.
    startTransition(async () => {
      try {
        await markAnnouncementSeen(current.id);
      } catch {
        /* best-effort */
      }
    });
  }, [queue]);

  // Nothing to show (not loaded, or no unseen announcements).
  if (!loaded || queue.length === 0) return null;
  if (typeof document === "undefined") return null;

  const current = queue[0];

  return createPortal(
    <div
      className="fixed inset-0 z-[70] flex items-center justify-center bg-black/70 p-4 backdrop-blur-sm"
      role="dialog"
      aria-modal="true"
      aria-labelledby="announcement-title"
      onClick={dismiss}
    >
      <div
        className="card w-full max-w-2xl overflow-hidden motion-safe:animate-panel-in"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="border-b border-white/[0.06] bg-gradient-to-r from-brand-500/10 to-accent-blue/10 px-6 py-4">
          <div className="flex items-center gap-2">
            <span className="flex h-6 w-6 items-center justify-center rounded-full bg-brand-500/20 text-brand-300">
              <svg
                width="14"
                height="14"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <path d="M11 3l1.8 4.9L17.7 9.7l-4.9 1.8L11 16.4l-1.8-4.9L4.3 9.7l4.9-1.8zM18 14.5l.85 2.15L21 17.5l-2.15.85L18 20.5l-.85-2.15L15 17.5l2.15-.85z" />
              </svg>
            </span>
            <span className="text-xs font-medium uppercase tracking-wider text-brand-300">
              What&apos;s new
            </span>
          </div>
          <h2
            id="announcement-title"
            className="mt-2 text-lg font-bold tracking-tight text-white"
          >
            {current.title}
          </h2>
          {current.serviceTypes.length > 0 && (
            <div className="mt-1.5 flex gap-1.5">
              {current.serviceTypes.map((t) => (
                <span
                  key={t}
                  className="rounded border border-white/10 bg-white/[0.05] px-1.5 py-0.5 text-[10px] text-slate-400"
                >
                  {t}
                </span>
              ))}
            </div>
          )}
        </div>

        {/* Body */}
        <div className="max-h-[60vh] overflow-y-auto px-6 py-5">
          {current.gameFamilies.length > 0 && (
            <div className="mb-4">
              <p className="mb-2 text-[11px] font-medium uppercase tracking-wide text-slate-500">
                {current.gameFamilies.length > 1 ? "Games covered in this update" : "Game"}
              </p>
              <div className={`grid gap-2 ${current.gameFamilies.length === 1 ? "grid-cols-3" : "grid-cols-4 sm:grid-cols-5"}`}>
                {current.gameFamilies.map((g) => (
                  <div key={g} className="overflow-hidden rounded-lg border border-white/10">
                    <GameCoverTile family={g} name={GAME_DISPLAY[g as GameFamily]?.name ?? g} />
                    <p className="truncate bg-black/40 px-1.5 py-1 text-center text-[10px] font-medium text-slate-200">
                      {GAME_DISPLAY[g as GameFamily]?.name ?? g}
                    </p>
                  </div>
                ))}
              </div>
            </div>
          )}
          <div
            dangerouslySetInnerHTML={{ __html: renderMarkdown(current.body) }}
          />
          {current.screenshotUrl && (
            <div className="mt-4">
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                src={current.screenshotUrl}
                alt={`Screenshot for ${current.title}`}
                className="w-full rounded-xl border border-white/10 shadow-lg shadow-black/20"
                loading="lazy"
              />
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="flex items-center justify-between border-t border-white/[0.06] px-6 py-4">
          <span className="text-xs text-slate-500">
            {queue.length > 1
              ? `1 of ${queue.length} updates`
              : ""}
          </span>
          <button className="btn-primary" onClick={dismiss}>
            {queue.length > 1 ? "Next" : "Got it"}
          </button>
        </div>
      </div>
    </div>,
    document.body,
  );
}
